// spec: specs/writing-submit.md (2.1–2.3) · кейсы WSB-03, WSB-04, WSB-05 · запасной путь (page.route, setOffline)
// seed: tests/seed.parent.spec.ts
// Общий ребёнок QA-AUTO-… (письмо 3) на файл → serial. Порог автоповтора (~15 с) и карточки (~31 с) — решение программиста
// (комментарий 01.11), проверяем только «повтор был, с тем же id» и «ожидание конечно»; ожидания — через expect с лимитом, без пауз.
// Не прогонять при записи — запуск только по /qa-regress.
import { BrowserContext, Page, Route } from '@playwright/test';
import { test, expect } from '../../fixtures';
import {
  SUBMIT_RPC,
  annotateCleanup,
  birthYearForAge,
  createChildWithLevels,
  handoverToChildHome,
  openSharedUserPage,
  openWritingCatalog,
  openWritingTask,
  qaChildName,
  qaWritingText,
  trackSubmits,
  typeDraft,
  writingSurface,
} from './writing.helpers';


// Пропущено 08.11 (решение пользователя): тест создаёт нового ребёнка QA-AUTO и передаёт ему устройство — с #8ca267 режим ребёнка серверный и запирает вход до ввода пароля/PIN.
test.skip(true, 'QA-AUTO + режим ребёнка запирает вход (#8ca267) — пропущено по решению 08.11');

test.describe.configure({ mode: 'serial' });

test.describe('Отправка письма — автоповтор, нет сети, 500 (autotest-writer)', () => {
  const childName = qaChildName();
  let childId = '';
  let kid: { context: BrowserContext; page: Page };
  let submits: ReturnType<typeof trackSubmits>;

  test.beforeAll(async ({ browser }, testInfo) => {
    test.setTimeout(2 * 60_000);
    kid = await openSharedUserPage(browser, testInfo, 'parent');
    childId = await createChildWithLevels(kid.page, childName, { birthYear: birthYearForAge(9), writingLevel: 3 });
    await handoverToChildHome(kid.page, childId, childName);
    submits = trackSubmits(kid.page);
  });

  test.afterAll(async () => {
    await kid?.context.close();
  });

  async function newTypedDraft(page: Page) {
    await openWritingCatalog(page, childId);
    await openWritingTask(page);
    await typeDraft(page, qaWritingText());
    submits.reset();
  }

  test('Нет ответа сервера: автоповтор с тем же id, затем «אופס, הייתה אצלי תקלה» + «ננסה שוב»; после «ננסה שוב» — отзыв, один id @desktop @data #b39e08', async ({}, testInfo) => {
    test.setTimeout(3 * 60_000);
    annotateCleanup(testInfo, childName, childId);
    const page = kid.page;
    const s = writingSurface(page);
    await newTypedDraft(page);

    // Держим все запросы отправки (ответа нет), пока не отпустим.
    const held: Route[] = [];
    let release!: () => void;
    const released = new Promise<void>((r) => (release = r));
    await page.route(`**${SUBMIT_RPC}*`, async (route) => {
      held.push(route);
      await released;
      await route.continue().catch(() => undefined);
    });
    try {
      await s.finish.click();
      await expect(s.confirm).toBeVisible();
      await s.send.click();
      await expect(s.processing).toBeVisible();

      // AC3 / реджект п.1: второй запрос (автоповтор) приходит сам, с тем же id (AC2)
      await expect.poll(() => submits.count(), { message: 'автоповтор не пришёл', timeout: 40_000 }).toBeGreaterThanOrEqual(2);
      const [first, second] = submits.requests;
      expect(second.at - first.at, 'автоповтор раньше 10 с').toBeGreaterThanOrEqual(10_000);
      expect(submits.keys(), `разные id отправки: ${submits.keys().join(', ')}`).toHaveLength(1);

      // Ожидание конечно: карточка D4 Timeout с «ננסה שוב» (AC3 «סטטוס … כשל וניסיון חוזר»)
      await expect(s.errorCard).toBeVisible({ timeout: 60_000 });
      await expect(s.retry).toBeVisible();
    } finally {
      release();
      await page.unroute(`**${SUBMIT_RPC}*`);
    }

    // Поздние ответы пришли; «ננסה שוב» → отзыв; все запросы — с одним id (AC2 «אינה יוצרת שתי תוצאות»)
    await s.retry.click();
    await expect(s.feedbackNext).toBeVisible({ timeout: 60_000 });
    expect(submits.keys(), `разные id отправки: ${submits.keys().join(', ')}`).toHaveLength(1);
  });

  test('Нет сети до «לשלוח»: «אין חיבור לאינטרנט» + «ננסה שוב»; после сети «ננסה שוב» → отзыв @desktop @data #b39e08', async ({}, testInfo) => {
    test.setTimeout(2 * 60_000);
    annotateCleanup(testInfo, childName, childId);
    const page = kid.page;
    const s = writingSurface(page);
    await newTypedDraft(page);

    await kid.context.setOffline(true);
    try {
      await s.finish.click();
      await expect(s.confirm).toBeVisible();
      await s.send.click();
      // Реджект п.2: ребёнку сказано, что нет сети, и есть повтор
      await expect(s.offlineCard).toBeVisible({ timeout: 30_000 });
      await expect(s.retry).toBeVisible();
    } finally {
      await kid.context.setOffline(false);
    }
    await s.retry.click();
    await expect(s.feedbackNext).toBeVisible({ timeout: 60_000 });
    expect(submits.keys().length, 'больше одного id отправки').toBeLessThanOrEqual(1);
  });

  test('500 на первые 2 запроса: автоповтор → карточка «ננסה שוב» → та же версия → отзыв @desktop @data #b39e08', async ({}, testInfo) => {
    test.setTimeout(3 * 60_000);
    annotateCleanup(testInfo, childName, childId);
    const page = kid.page;
    const s = writingSurface(page);
    await newTypedDraft(page);

    let failed = 0;
    await page.route(`**${SUBMIT_RPC}*`, async (route) => {
      if (failed < 2) {
        failed++;
        await route.fulfill({ status: 500, contentType: 'application/json', body: '{"message":"QA-AUTO forced 500"}' });
      } else {
        await route.continue();
      }
    });
    try {
      await s.finish.click();
      await expect(s.confirm).toBeVisible();
      await s.send.click();
      // AC3: после двух сбоев — карточка с «ננסה שוב», а не бесконечное ожидание
      await expect.poll(() => failed, { message: 'автоповтора после первого 500 не было', timeout: 40_000 }).toBe(2);
      await expect(s.retry).toBeVisible({ timeout: 60_000 });

      await s.retry.click();
      await expect(s.feedbackNext).toBeVisible({ timeout: 60_000 });
      // AC3 «בלי לאבד את גרסת ההגשה»: все запросы — с одним id
      expect(submits.count()).toBeGreaterThanOrEqual(3);
      expect(submits.keys(), `разные id отправки: ${submits.keys().join(', ')}`).toHaveLength(1);
    } finally {
      await page.unroute(`**${SUBMIT_RPC}*`);
    }
  });
});
